-- Frozen differential fixtures generated from real NumPy 2.3.5
local np=require("luaray_core")
assert(np._version=="0.99.0-dev")
local checks,cases=0,0
local function deep(a,b,desc)
    assert(type(a)==type(b),desc..': type mismatch: '..type(a)..' vs '..type(b))
    if type(a)=='table' then
        assert(#a==#b,desc..': length mismatch: '..#a..' vs '..#b)
        for i=1,#a do deep(a[i],b[i],desc..'['..i..']') end
    else
        assert(a==b,desc..': '..tostring(a)..' vs '..tostring(b))
    end
    checks=checks+1
end
do
local r=np.random.default_rng(4294967297)
local x=np.astype(np.arange(0,"int64"):reshape({2,0}),"int32")
local before=x:tolist()
local out=np.zeros({2,0},"int32")
local y=r:permuted(x,2,out)
deep(y.dtype,"int32","4294967297/(2, 0)/int32/plain/1/out_new dtype")
deep(y:tolist(),{{},{}},"4294967297/(2, 0)/int32/plain/1/out_new values")
deep(x:tolist(),{{},{}},"4294967297/(2, 0)/int32/plain/1/out_new source")
assert(rawequal(y,out),"out must return identical ndarray")
deep(r:raw_hex(),"54f596cd84cf4c1f","4294967297/(2, 0)/int32/plain/1/out_new pcg")
cases=cases+1; end
